export function tally(rows: number[][][]): number {
	let sum = 0;
	for (const plane of rows) {
		sum += gain(plane);
	}
	return sum;
}

function gain(plane: number[][]): number {
	let sum = 0;
	for (const row of plane) {
		for (const cell of row) {
			if (cell > 0) {
				sum += cell;
			}
		}
	}
	return sum;
}
